/**
 * Parity test against api/birth-chart.js's apparence() (astronomia/VSOP87) — not a fresh Swiss
 * Ephemeris comparison, since distance/phase are pure geometry once position is right, and
 * position is already validated elsewhere in this package ("cosmétique, pas de la géométrie",
 * docs/A-FAIRE.md 2026-08-22). Reference values below were generated by running the ORIGINAL
 * apparence() against these exact two dates.
 */
import { describe, it, expect, beforeAll } from 'vitest'
import { createAstronomyEngine, AstronomyEngineProvider, CelestialBody } from '../src'

describe('AstronomyEngine.getApparentDisk', () => {
  let engine: ReturnType<typeof createAstronomyEngine>

  beforeAll(() => {
    engine = createAstronomyEngine({ provider: new AstronomyEngineProvider() })
  })

  const paris = new Date('2000-01-01T12:00:00.000Z')
  const sydney = new Date('2026-08-22T00:00:00.000Z')

  // { body, date, ua|km, arcsec, phase } — from the OLD apparence(), astronomia/VSOP87
  const cases: Array<{ label: string; date: Date; body: CelestialBody; distance: number; unit: 'au' | 'km'; sec: number; phase: number }> = [
    { label: 'Sun, Paris',      date: paris,  body: CelestialBody.Sun,     distance: 0.983,    unit: 'au', sec: 1951.81,  phase: 1 },
    { label: 'Moon, Paris',     date: paris,  body: CelestialBody.Moon,    distance: 402445,   unit: 'km', sec: 1780.926, phase: 0.229 },
    { label: 'Mercury, Paris',  date: paris,  body: CelestialBody.Mercury, distance: 1.416,    unit: 'au', sec: 4.753,    phase: 0.975 },
    { label: 'Venus, Paris',    date: paris,  body: CelestialBody.Venus,   distance: 1.138,    unit: 'au', sec: 14.669,   phase: 0.758 },
    { label: 'Mars, Paris',     date: paris,  body: CelestialBody.Mars,    distance: 1.85,     unit: 'au', sec: 5.053,    phase: 0.926 },
    { label: 'Jupiter, Paris',  date: paris,  body: CelestialBody.Jupiter, distance: 4.621,    unit: 'au', sec: 41.718,   phase: 0.991 },
    { label: 'Saturn, Paris',   date: paris,  body: CelestialBody.Saturn,  distance: 8.653,    unit: 'au', sec: 18.558,   phase: 0.998 },
    { label: 'Uranus, Paris',   date: paris,  body: CelestialBody.Uranus,  distance: 20.727,   unit: 'au', sec: 3.374,    phase: 1 },
    { label: 'Neptune, Paris',  date: paris,  body: CelestialBody.Neptune, distance: 31.024,   unit: 'au', sec: 2.189,    phase: 1 },
    { label: 'Sun, Sydney',     date: sydney, body: CelestialBody.Sun,     distance: 1.012,    unit: 'au', sec: 1897.432, phase: 1 },
    { label: 'Moon, Sydney',    date: sydney, body: CelestialBody.Moon,    distance: 404571,   unit: 'km', sec: 1771.567, phase: 0.676 },
    { label: 'Mercury, Sydney', date: sydney, body: CelestialBody.Mercury, distance: 1.312,    unit: 'au', sec: 5.127,    phase: 0.972 },
    { label: 'Venus, Sydney',   date: sydney, body: CelestialBody.Venus,   distance: 0.632,    unit: 'au', sec: 26.386,   phase: 0.449 },
    { label: 'Mars, Sydney',    date: sydney, body: CelestialBody.Mars,    distance: 1.902,    unit: 'au', sec: 4.913,    phase: 0.924 },
    { label: 'Jupiter, Sydney', date: sydney, body: CelestialBody.Jupiter, distance: 6.25,     unit: 'au', sec: 30.843,   phase: 0.999 },
    { label: 'Saturn, Sydney',  date: sydney, body: CelestialBody.Saturn,  distance: 8.708,    unit: 'au', sec: 18.441,   phase: 0.999 },
    { label: 'Uranus, Sydney',  date: sydney, body: CelestialBody.Uranus,  distance: 19.539,   unit: 'au', sec: 3.579,    phase: 0.999 },
    { label: 'Neptune, Sydney', date: sydney, body: CelestialBody.Neptune, distance: 29.044,   unit: 'au', sec: 2.338,    phase: 1 },
  ]

  it.each(cases)('matches the old astronomia apparence() within tolerance — $label', async ({ date, body, distance, unit, sec, phase }) => {
    const disk = await engine.getApparentDisk(body, date)
    if (unit === 'au') {
      expect(disk.distanceAU).not.toBeNull()
      expect(Math.abs((disk.distanceAU as number) - distance)).toBeLessThan(0.01)
    } else {
      expect(disk.distanceKm).not.toBeNull()
      expect(Math.abs((disk.distanceKm as number) - distance)).toBeLessThan(50) // km, negligible vs 400,000+ km range
    }
    expect(Math.abs(disk.angularSizeArcsec - sec)).toBeLessThan(0.5)
    expect(Math.abs(disk.phase - phase)).toBeLessThan(0.01)
  })
})
